<script setup>
import { ref } from 'vue';
import { workspace } from '../../services/workspace.js';
import { useCollection,money,date,statuses,fulfillments } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
import DataTable from '../../components/DataTable.vue';
const filter=ref(''),{rows,loading,error,meta,updateQuery}=useCollection(()=>workspace.activeStoreId?`/stores/${workspace.activeStoreId}/orders`:null,()=>filter.value?{status:filter.value}:{});
const columns=[{key:'number',label:'Pedido'},{key:'customer.name',label:'Cliente'},{key:'total',label:'Total'},{key:'status',label:'Pago'},{key:'fulfillmentStatus',label:'Entrega'}];
</script>
<template><div><header class="p-page-header"><div><p class="p-eyebrow">DE TU TIENDA A SUS MANOS</p><h1>Pedidos</h1><p>Seguí cada venta, verificá cobros y mantené tus entregas organizadas.</p></div><RouterLink v-if="workspace.activeStoreId" to="/app/orders/new" class="btn btn-primary"><Icon name="plus" :size="16"/>Crear pedido</RouterLink></header><div v-if="error" class="p-error">{{error}}</div><DataTable :rows="rows" :columns="columns" :loading="loading" server :total="meta.total" :page="meta.page" :limit="meta.limit" @query-change="updateQuery" search-placeholder="Buscar pedido o cliente..." empty-text="Los pedidos aparecerán acá cuando lleguen."><template #toolbar><select v-model="filter" class="p-table-input" style="width:auto;min-width:170px" aria-label="Filtrar por estado de pago" @change="updateQuery({page:1})"><option value="">Todos los estados</option><option v-for="(label,value) in statuses" :key="value" :value="value">{{label}}</option></select></template><template #cell-number="{row}"><strong>#{{row.number||row._id.slice(-6).toUpperCase()}}</strong><small>{{date(row.createdAt)}}</small></template><template #cell-customer.name="{row}"><strong>{{row.customer?.name}}</strong><small>{{row.customer?.email}}</small></template><template #cell-total="{value}"><strong>{{money(value)}}</strong></template><template #cell-status="{row}"><span class="p-badge dot" :class="row.status">{{statuses[row.status]||row.status}}</span><small v-if="['paid','cancelled'].includes(row.status)">Estado final</small></template><template #cell-fulfillmentStatus="{value}">{{fulfillments[value]||value}}</template><template #actions="{row}"><RouterLink :to="`/app/orders/${row._id}`" class="btn btn-secondary btn-small"><Icon name="eye" :size="13"/>Ver pedido</RouterLink></template></DataTable></div></template>
